"""B1538 -- THE PUNCTURE CHARACTERS: the lock (banked PROVED, room for two; run as sealed, the records regenerated by the
sealed code after the originals were lost, and every number of the first read-out reproduced).

  - seal integrity: every file of ARTIFACT_HASHES.txt hashes as sealed;
  - the controls K0-K12 recorded in controls.json all hold, with K10's structure (Proposition H's ten covers, the two golden
    ones, and the identity class of each silver state), K11's manifest (80 covers, 108 chunks, the seal's totals) and K12's
    fourth-root certificate (40 covers);
  - the read-out's logic on synthetic rows (P4-P6, the Part F branches, the audit lane's R87 coverage cases, and
    Proposition H's P9-P11);
  - route W reproduces the figure-eight's Burau/Alexander identity (control K7) at two roots of unity;
  - the population's structure on m004 and m003: 5 and 9 covers, b1 = #cusps (Lemma 2), the puncture-trivial subgroup of
    order |det(M - 1)| (Lemma 3), free rank #cusps - 1;
  - the addendum (Part F'): the driver's scope order, block shape and resumption, and the scoped verdict's cases, on
    synthetic data only; control K13 recorded identical; the sealed aggregates' arithmetic.
  - the banked records (the raw records' sha-256 inside the .gz files, the append's record), the read-outs on them, the
    comparison with the 31 recorded numbers, and the verdict's records (THEOREM_REGISTRY, FINDINGS).
sm:B1536's route_r resets PARI's stack when imported, so nothing here imports punct_four (or controls.py, which does).
Instruments are imported inside the tests: sm:B1527's cusp_lib sets mpmath's precision when imported."""
import hashlib
import importlib.util
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
ARC = ROOT / "frontier" / "B1538_the_puncture_characters"
V = ARC / "verification"


def _load(name, alias):
    spec = importlib.util.spec_from_file_location(alias, V / (name + ".py"))
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def _lib():
    if str(V) not in sys.path:
        sys.path.insert(0, str(V))
    import punct_covers as F
    import punct_transfer as T
    import punct_wang as W
    return F, T, W


def test_seal_integrity():
    lines = [ln for ln in (ARC / "ARTIFACT_HASHES.txt").read_text().splitlines() if ln.strip() and not ln.startswith("#")]
    assert len(lines) >= 11
    for ln in lines:
        h, name = ln.split(None, 1)
        assert hashlib.sha256((ARC / name).read_bytes()).hexdigest() == h, name


def test_controls_recorded():
    c = json.loads((V / "controls.json").read_text())
    assert c["all hold"] is True
    for k in ("K0", "K1", "K2", "K3", "K4", "K5", "K6", "K7", "K8", "K9", "K10", "K11", "K12"):
        assert c[k]["holds"] is True, k
    assert c["K1"]["rows"] == 541 and c["K2"]["covers"] == 80 and len(c["K9"]["cases"]) == 26
    assert c["K12"]["covers"] == 40 and c["K12"]["failure count"] == 0
    h = c["K10"]
    assert h["count"] == 10 and h["golden covers"] == ["m003.D4.2-0-2.w0", "m004.D4.2-0-2.w0"]
    assert h["identity covers"] == ["m135.D4.2-0-2.w0", "m136.D4.2-0-2.w3"]
    assert all(v["m"] == 2 and all(v["checks"].values()) for v in h["covers"].values())
    m = c["K11"]
    assert len(m["manifest"]) == 80 and m["chunks"] == 108
    assert m["totals"] == {"m004": [5, 583, 201], "m003": [9, 39695, 7313], "m136": [29, 807820, 210524],
                           "m135": [37, 1558524, 444950]}


def test_read_out_logic():
    RO = _load("read_out", "b1538_read_out_lock")

    def cover(state, hits, chunks=1):
        return {"cover": state + ".x", "chunk": 0, "chunks": chunks, "state": state, "read": True, "puncture orbits": 4,
                "puncture characters": 8, "hits": hits, "route P": {"reads": 5, "disagree": []},
                "route T": {"reads": len(hits), "skipped": 0, "disagree": []}}

    def man(*cids, chunks=1):
        return {c: {"chunks": chunks, "puncture orbits": 4} for c in cids}

    def hit(n):
        return {"n": n, "zeta": [1], "m": 2, "s": [1, 2], "h1": n, "trivial cusps": 0}
    chi = {"zeta": [1], "m": 2, "s": [1, 2], "n": 2}
    q = lambda s: None  # noqa: E731
    ident = {"identity holds": True}
    p = RO.evaluate(ident, [cover("m003", [])], None, say=q, manifest=man("m003.x"))["predictions"]
    assert (p["P4"], p["P5"], p["P6"], p["P8"]) == (False, True, True, True)
    p = RO.evaluate(ident, [cover("m004", [hit(1)])], None, say=q, manifest=man("m004.x"))["predictions"]
    assert (p["P4"], p["P5"], p["P6"]) == (True, True, False)
    # the audit lane's R87: a missing cover, or a candidate with an empty Part F, certifies nothing
    out = RO.evaluate(ident, [cover("m003", [])], None, say=q, manifest=man("m003.x", "m135.x"))
    assert out["every cover read"] is False and (out["predictions"]["P4"], out["predictions"]["P8"]) == (None, None)
    p = RO.evaluate(ident, [cover("m135", [hit(2)])], [], say=q, manifest=man("m135.x"))["predictions"]
    assert (p["P7"], p["P8"]) == (None, None)
    head = {"kind": "candidate", "cover": "m135.x", "chi": chi, "planned": 1}
    both = {"kind": "reading", "cover": "m135.x", "chi": chi, "nu": {"zeta": [1], "m": 8, "s": [1, 8]}, "member": True,
            "h1 R": 1, "h1 P4": 1, "R": {"capW": 2, "capL2": 2}, "P4": {"capW": 2, "capL2": 2}}
    p = RO.evaluate(ident, [cover("m135", [hit(2)])], [head, both], say=q, manifest=man("m135.x"))["predictions"]
    assert (p["P5"], p["P7"], p["P8"]) == (False, False, False)
    p = RO.evaluate(ident, [cover("m135", [hit(2)])], None, say=q, manifest=man("m135.x"))["predictions"]
    assert p["P7"] is None and p["P8"] is None
    # Proposition H: the sum of n at zeta_H is 4; at most 2 at one s where tau moves Q8; even where tau fixes it
    gold = {"m004.x": {"ez": [1, 1], "m": 2, "golden": True, "acts on Q8 as the identity": False}}
    fixed = {"m135.x": {"ez": [1, 1], "m": 2, "golden": False, "acts on Q8 as the identity": True}}

    def qh(n, s):
        return {"n": n, "zeta": [1, 1], "m": 2, "s": s, "h1": n, "trivial cusps": 0}
    p = RO.evaluate(ident, [cover("m004", [qh(2, [1, 6]), qh(1, [1, 3]), qh(1, [2, 3])])], None, say=q, hcov=gold,
                    manifest=man("m004.x"))["predictions"]
    assert (p["P9"], p["P10"], p["P11"]) == (True, True, None)
    p = RO.evaluate(ident, [cover("m004", [qh(3, [1, 6]), qh(1, [1, 3])])], None, say=q, hcov=gold,
                    manifest=man("m004.x"))["predictions"]
    assert (p["P9"], p["P10"]) == (True, False)
    p = RO.evaluate(ident, [cover("m135", [qh(2, [0, 1]), qh(1, [1, 4])])], None, say=q, hcov=fixed,
                    manifest=man("m135.x"))["predictions"]
    assert (p["P9"], p["P10"], p["P11"]) == (False, None, False)
    p = RO.evaluate(ident, [cover("m004", [qh(4, [0, 1])], chunks=2)], None, say=q, hcov=gold,
                    manifest=man("m004.x", chunks=2))["predictions"]
    assert (p["P9"], p["P10"], p["P11"]) == (None, None, None)


def test_route_w_burau_identity():
    F, T, W = _lib()
    from cypari import pari as P
    s1 = {"a": "abA", "b": "a", "c": "c"}
    s2i = {"a": "a", "b": "c", "c": "Cbc"}
    img = {g: g for g in "abc"}
    for step in (s2i, s1, s2i, s1):
        img = {g: F.substitute(img[g], step) for g in "abc"}
    idx = {"a": 0, "b": 1, "c": 2}
    images = [[(idx[c.lower()], 1 if c.islower() else -1) for c in img[g]] for g in "abc"]
    for m in (7, 12):
        Jb, _ = W.jbar(W.fox_jacobian(images, [1, 1, 1], m), [1, 1, 1], m)
        z = P.Mod(P("y"), P.polcyclo(m, "y"))
        ratio = P.subst(P.charpoly(Jb, "x"), "x", 1) / ((1 + z + z ** 2) * (z ** 2 - 3 * z + 1))
        assert ratio ** (2 * m) == 1, m


def test_structure_m004_m003():
    F, T, W = _lib()
    for sw, ncov, det in (("+LR", 5, 1), ("-LR", 9, 5)):
        st = F.State(sw)
        cv = F.covers(st, 12)
        assert len(cv) == ncov
        for lat, w in cv:
            C = F.Cover(st, lat, w)
            assert C.free_rank == len(C.cusps) - 1
            pt, _ = C.puncture_trivial()
            assert len(pt) == det
            r = T.read(C, [0] * C.n, 0, 1)
            assert r["b1"] == r["cusps"] == len(C.cusps)


def test_addendum_part_f_prime_logic(tmp_path, monkeypatch):
    DR = _load("run_f_scoped", "b1538_run_f_scoped_lock")
    RS = _load("read_out_scoped", "b1538_read_out_scoped_lock")
    add = (ARC / "PREREGISTRATION_ADDENDUM.md").read_text()
    assert "BANKED IDENTITY:" in add and "PRIOR ART:" in add and "12,152 candidates and 501,792 planned readings" in add
    # the sealed aggregates add up
    S = DR.SEALED
    assert S["in scope"] + S["out of scope"] == S["candidates"] == 64422
    assert S["in scope, planned readings"] + S["out of scope, planned readings"] == S["planned readings"] == 948832288
    assert sum(v[0] for v in S["in scope, by state"].values()) == S["in scope"]
    assert sum(v[1] for v in S["in scope, by state"].values()) == S["in scope, planned readings"]
    assert DR.CAP == 1024 and DR.GOLDEN == ("+LR", "-LR")

    # the scope's order: golden first in the record's order, then silver by planned readings (stable)
    def cand(word, planned, tag):
        return {"row": {"word": word, "cover": tag}, "state": "x", "key": [tag, [0], 2, [1, 2]], "planned": planned,
                "in scope": word in DR.GOLDEN or planned <= DR.CAP}
    cs = [cand("+LLRR", 8, "s8"), cand("+LR", 64, "g1"), cand("-LLRR", 0, "s0"), cand("-LLRR", 2048, "out"),
          cand("-LR", 16, "g2"), cand("+LLRR", 0, "s0b")]
    assert [c["row"]["cover"] for c in DR.scope_order(cs)] == ["g1", "g2", "s0", "s0b", "s8"]

    # a block: one header for its candidate, then exactly its planned rows
    import json as _j
    chi = {"zeta": [1, 0], "m": 4, "s": [1, 2], "n": 2}

    def block(cover, planned, rows=None):
        head = {"kind": "candidate", "cover": cover, "chi": chi, "fourth roots": planned // 4,
                "fourth roots by the Smith form": planned // 4, "planned": planned}
        rd = [{"kind": "reading", "cover": cover, "chi": chi, "nu": {"zeta": [i], "m": 8, "s": [1, 8]}}
              for i in range(planned if rows is None else rows)]
        return "".join(_j.dumps(x) + "\n" for x in [head] + rd)
    c1 = {"key": ["A", [1, 0], 4, [1, 2]], "planned": 4}
    c2 = {"key": ["B", [1, 0], 4, [1, 2]], "planned": 8}
    assert DR.block_ok(block("A", 4), c1)
    assert not DR.block_ok(block("A", 4, rows=3), c1)
    assert not DR.block_ok(block("B", 4), c1)
    assert not DR.block_ok(block("A", 4).rstrip("\n"), c1)
    # resumption keeps whole candidates only and cuts an incomplete tail (a temporary file, never the record)
    out = tmp_path / "run_F_scoped.jsonl"
    monkeypatch.setattr(DR, "OUT", out)
    out.write_text(block("A", 4) + block("B", 8, rows=5))
    assert DR.resume([c1, c2]) == 1 and out.read_text() == block("A", 4)
    out.write_text(block("A", 4) + block("B", 8))
    assert DR.resume([c1, c2]) == 2

    # the verdict's cases (the addendum's section 4)
    def sealed(**kw):
        p = {"P1": True, "P2": True, "P3": True, "P9": True, "P8": None}
        p.update(kw)
        return {"predictions": p}
    assert RS.verdict(sealed(P8=False), None) == "PROVED"
    assert RS.verdict(sealed(), True) == "NEGATIVE"
    assert RS.verdict(sealed(), None) == "OPEN"
    assert RS.verdict(sealed(), False) == "OPEN"
    assert RS.verdict(sealed(P2=None), True) == "OPEN"
    assert RS.verdict(sealed(P9=False, P8=False), None) == "OPEN"

    # control K13: the driver's path reproduced the sealed partial record's first lines
    k = json.loads((V / "control_k13.json").read_text())
    assert k["identical"] is True and k["lines compared"] == 2000
    assert k["sha-256 of the sealed partial's first lines"] == k["sha-256 of the driver's first lines"]


def test_the_banked_records():
    """the records regenerated by the sealed code and banked unread: the raw records' sha-256 inside the .gz files"""
    import gzip
    for name in ("run_L", "run_F"):
        sha = dict(reversed(ln.split()) for ln in (V / f"{name}_sha256.txt").read_text().splitlines() if ln.strip())
        raw = gzip.decompress((V / f"{name}.jsonl.gz").read_bytes())
        assert hashlib.sha256(raw).hexdigest() == sha[f"{name}.jsonl"], name
    app = json.loads((V / "run_F_append.json").read_text())
    assert app["run_F.jsonl before (the sealed partial record)"].startswith("1e9c6e5550f2bb46")
    assert (app["Part F' candidates"], app["Part F' readings"], app["lines after"]) == (12152, 501792, 526770)
    assert app["run_F.jsonl after (the partial record, then Part F')"] == sha["run_F.jsonl"]


def test_the_banked_read_outs():
    """the sealed read-out (its second execution, on the regenerated records), the scoped read-out, and the comparison
    with every number recorded from the first read-out of 2026-10-04"""
    ro = json.loads((V / "read_out.json").read_text())
    assert ro["predictions"] == {"P1": True, "P2": True, "P3": True, "P4": True, "P5": False, "P6": False, "P7": False,
                                 "P8": False, "P9": True, "P10": True, "P11": True}
    assert ro["every cover read"] is True and ro["puncture orbits read"] == 662988
    assert ro["puncture characters read"] == 2406622
    assert ro["hits (n >= 1), Galois orbits"] == 483692 and ro["candidates (n >= 2)"] == 64422 and ro["max n"] == 5
    assert ro["n distribution"] == {"1": 419270, "2": 63619, "3": 696, "4": 105, "5": 2}
    assert ro["route P"] == {"reads": 3376190, "disagree": 0}
    assert ro["route T"] == {"reads": 483692, "disagree": 0, "skipped": 0}
    assert ro["Proposition H"]["covers"] == 10 and set(ro["Proposition H"]["sum of n"].values()) == {4}
    rs = json.loads((V / "read_out_scoped.json").read_text())
    assert (rs["P7'"], rs["P8'"], rs["verdict"]) == (False, False, "PROVED")
    pf = rs["Part F (in scope)"]
    assert pf["complete"] is True and pf["routes agree"] is True
    assert (pf["candidates"], pf["readings"], pf["members"], pf["members with capL2 >= 2"]) == (12152, 501792, 10346, 5592)
    rc = json.loads((V / "regen_compare.json").read_text())
    assert rc["every recorded number reproduced"] is True and rc["differences"] == {}
    assert len(rc["recorded (the relay of 2026-10-06, section 3)"]) == 31
    assert rc["descriptive (not recorded numbers)"]["Part F': rooms of the members (route R)"] == {
        "0": 938, "1": 3816, "2": 3736, "3": 1856}
    assert rc["regenerated"]["Part F': the covers of the members with room 3"] == [
        "m135.D8.2-0-4.w1", "m135.D8.4-0-2.w4", "m136.D8.2-0-4.w3", "m136.D8.4-0-2.w5"]


def test_the_verdict_and_its_records():
    v = json.loads((ARC / "arc_verdict.json").read_text())
    assert v["id"] == "B1538" and v["verdict"] == "PROVED" and v["creates_law"] is True and v["instrument"] is False
    lb = importlib.util.spec_from_file_location("b1538_load_bearing_lock", ROOT / "scripts" / "checks" / "load_bearing.py")
    mod = importlib.util.module_from_spec(lb)
    lb.loader.exec_module(mod)
    assert mod.validate(v["load_bearing"], v["scope"]) == []
    reg = (ROOT / "docs" / "THEOREM_REGISTRY.md").read_text()
    assert "| T-THE-QUATERNION-LINE |" in reg and "| T-THE-PUNCTURE-ROOM |" in reg
    f = (ARC / "FINDINGS.md").read_text()
    assert "cc (the SM-derivation seat), 2026-10-06." in f and "## Seen first" in f
    assert "Every number was reproduced, with no difference" in f
